import { Component, input, output } from '@angular/core';
import { Verse } from 'src/app/common/verse/verse';
import { VerseCardComponent } from 'src/app/common/verse/verse-card/verse-card.component';

@Component({
  selector: 'app-results',
  templateUrl: './results.component.html',
  styleUrls: ['./results.component.scss'],
  imports: [VerseCardComponent],
})
export class ResultsComponent {
  hideFavoriteButton = input<boolean>(false);
  hideTagButton = input<boolean>(false);
  results = input<Verse[]>([]);
  error = input<string>('');
  versesRoute = input<string>();

  favoriteRemoved = output<void>();
  tagsChanged = output<void>();

  onFavoriteRemoved() {
    this.favoriteRemoved.emit();
  }

  onTagsChanged() {
    this.tagsChanged.emit();
  }
}
